def solve(clue):
    """Build two k-digit strings X, Y such that every digit of Y is the same digit of X
    with strictly more segments lit on a seven-segment display, and exactly n segments are
    added in total.  Realisations are chosen at random from all pairs with the required
    gain, so successive demos show different digits and different splits of n."""
    n, k = (int(t) for t in clue.split())
    r = random.Random(clue)
    M = [63, 6, 91, 79, 102, 109, 125, 7, 127, 111]
    P = {}
    for x in range(10):
        for y in range(10):
            if x != y and M[x] & ~M[y] == 0:
                P.setdefault(bin(M[y] ^ M[x]).count("1"), []).append((x, y))
    for _ in range(200):
        parts = [1] * k
        rem = n - k
        guard = 0
        while rem > 0 and guard < 10000:
            guard += 1
            i = r.randrange(k)
            if parts[i] < 5:
                parts[i] += 1
                rem -= 1
        if rem:
            return ""
        r.shuffle(parts)
        if all(p in P for p in parts):
            X = []
            Y = []
            for p in parts:
                x, y = P[p][r.randrange(len(P[p]))]
                X.append(str(x))
                Y.append(str(y))
            return "".join(X) + " " + "".join(Y)
    return ""

